psScript:
# user32.dll 点击坐标 (x, y)
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class Mouse {
  [DllImport("user32.dll")] public static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint dwData, UIntPtr dwExtraInfo);
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
}
"@
[System.Reflection.Assembly]::LoadWithPartialName("System.Windows.Forms") > $null
# 把下面的坐标改成你按钮的屏幕坐标（用屏幕尺子或类似工具测量）
$x = 465; $y = 361
[Mouse]::SetCursorPos($x, $y)
Start-Sleep -Milliseconds 200
[Mouse]::mouse_event(0x0002, 0, 0, 0, [UIntPtr]::Zero)  # 按下
[Mouse]::mouse_event(0x0004, 0, 0, 0, [UIntPtr]::Zero)  # 抬起
Write-Host "已点击 ($x, $y)"

# === 高 DPI 适配：防止 125%/150% 缩放屏坐标偏移 ===
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class Mouse {
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
  [DllImport("user32.dll")] public static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint dwData, UIntPtr dwExtraInfo);
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
}
"@
[Mouse]::SetProcessDPIAware() | Out-Null

# === 可选：先激活目标程序窗口（把引号里改成窗口标题）===
# $wshell = New-Object -ComObject WScript.Shell
# $wshell.AppActivate("窗口标题")
# Start-Sleep -Milliseconds 500

# === 坐标：用表单里的「拾取屏幕坐标」按钮自动抓取（物理像素，已按缩放转换）===
$x = 576; $y = 1346
[Mouse]::SetCursorPos($x, $y)
Start-Sleep -Milliseconds 200
[Mouse]::mouse_event(0x0002, 0, 0, 0, [UIntPtr]::Zero)  # 左键按下
[Mouse]::mouse_event(0x0004, 0, 0, 0, [UIntPtr]::Zero)  # 左键抬起
Write-Host "已点击 ($x, $y)"
